    [DataContract] class CodecResult {[DataMember(Name="path")]public string Path;[DataMember(Name="error")]public string Error;}
    [DataContract] sealed class WebpReceipt { [DataMember(Name="spec")]public string Spec;[DataMember(Name="source")]public string Source;[DataMember(Name="sha256")]public string Hash;[DataMember(Name="path")]public string Path;[DataMember(Name="error")]public string Error;[DataMember(Name="frames")]public int Frames;[DataMember(Name="length")]public long Length;}
    public static class AssetCodec {
        static void Stop(Process process){try{if(!process.HasExited)Process.Start(new ProcessStartInfo("taskkill.exe","/PID "+process.Id+" /T /F"){UseShellExecute=false,CreateNoWindow=true});}catch{try{process.Kill();}catch{}}}
        public static bool Encoded(byte[] bytes){return bytes.Length>=12&&((Encoding.ASCII.GetString(bytes,0,4)=="RIFF"&&Encoding.ASCII.GetString(bytes,8,4)=="WEBP")||Encoding.ASCII.GetString(bytes,4,4)=="ftyp"||(bytes[0]==26&&bytes[1]==69&&bytes[2]==223&&bytes[3]==163));}
        static string Python(){string bundled=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"runtime","python","python.exe");if(File.Exists(bundled))return bundled;string marker=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"codecs","python-path.txt");if(File.Exists(marker)){string path=File.ReadAllText(marker).Trim();if(File.Exists(path))return path;}string installed=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","Python","Python311","python.exe");return File.Exists(installed)?installed:"python.exe";}
        static readonly ConcurrentDictionary<string,SemaphoreSlim> webpLocks=new ConcurrentDictionary<string,SemaphoreSlim>();
        static string Digest(string path){using(var stream=File.OpenRead(path))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
        public static string AnimatedWebp(string source,CancellationToken cancel){
            cancel.ThrowIfCancellationRequested();if(new FileInfo(source).Length>30*1024*1024)throw new Exception("30MB 이하 움짤만 변환해요.");string hash=Digest(source),folder=Path.Combine(DcShop.CacheRoot,"webp-attachments-v3"),file=Path.Combine(folder,hash+".webp"),receipt=Path.ChangeExtension(file,".json");var gate=webpLocks.GetOrAdd(hash,key=>new SemaphoreSlim(1));gate.Wait(cancel);
            try{if(File.Exists(file)&&File.Exists(receipt))try{var cached=GemmaHost.Read<WebpReceipt>(File.ReadAllText(receipt));if(cached!=null&&cached.Spec=="animated-webp-lossless-v3"&&cached.Source==hash&&cached.Frames>=2&&new FileInfo(file).Length==cached.Length&&Digest(file)==cached.Hash)return file;}catch(IOException){}catch(SerializationException){}
                string script=Path.Combine(SemanticSearch.Root,"animated-webp.py");string staged=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"pending-semantic","animated-webp.py");if(!new[]{"AgitCon.exe","AjitCon.exe"}.Contains(Path.GetFileName(Process.GetCurrentProcess().MainModule.FileName),StringComparer.OrdinalIgnoreCase)&&File.Exists(staged))script=staged;var info=new ProcessStartInfo(Python(),"\""+script+"\" \""+Path.GetFullPath(source)+"\" \""+folder+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8};info.EnvironmentVariables["PYTHONUTF8"]="1";
                using(var process=Process.Start(info))using(cancel.Register(()=>Stop(process))){var output=process.StandardOutput.ReadToEndAsync();var errors=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(75000)){Stop(process);throw new Exception("WebP 변환 시간이 초과됐어요.");}cancel.ThrowIfCancellationRequested();string json=output.GetAwaiter().GetResult();if(String.IsNullOrWhiteSpace(json))throw new Exception("WebP 변환 스크립트가 결과를 반환하지 않았어요.");var result=GemmaHost.Read<WebpReceipt>(json);if(process.ExitCode!=0||!String.IsNullOrEmpty(result.Error)||result.Frames<2||result.Spec!="animated-webp-lossless-v3"||result.Source!=hash||!String.Equals(result.Path,file,StringComparison.OrdinalIgnoreCase)||!File.Exists(file)||Digest(file)!=result.Hash)throw new Exception("움직이는 WebP 변환을 확인하지 못했어요. "+result.Error);return file;}
            }finally{gate.Release();}
        }
        static readonly SemaphoreSlim resizeGate=new SemaphoreSlim(1);
        public static string ResizeForSend(string source,bool enabled,CancellationToken cancel){
            if(!enabled)return source;cancel.ThrowIfCancellationRequested();
            if(new FileInfo(source).Length>30*1024*1024)throw new InvalidDataException("30MB 이하 이미지만 축소해요.");
            string name=Path.GetFileNameWithoutExtension(source);if(name.Length>64)name=name.Substring(0,44)+name.Substring(name.Length-20);string folder=Path.Combine(ImageBundle.OutputRoot,"resize100-v1",Digest(source));resizeGate.Wait(cancel);
            try{Directory.CreateDirectory(folder);foreach(string existing in new[]{Path.Combine(folder,name+".png"),Path.Combine(folder,name+".gif")})if(File.Exists(existing))try{using(var image=System.Drawing.Image.FromFile(existing))if(image.Width==100&&image.Height==100)return existing;}catch(ArgumentException){}
                byte[] bytes=Convert(File.ReadAllBytes(source),cancel,true);cancel.ThrowIfCancellationRequested();bool gif=bytes.Length>6&&Encoding.ASCII.GetString(bytes,0,3)=="GIF";string file=Path.Combine(folder,name+(gif?".gif":".png"));
                using(var memory=new MemoryStream(bytes))using(var image=System.Drawing.Image.FromStream(memory)){if(image.Width!=100||image.Height!=100)throw new InvalidDataException("100×100 변환 결과를 확인하지 못했어요.");}
                string temporary=Path.Combine(folder,Guid.NewGuid().ToString("N").Substring(0,12)+".tmp");try{File.WriteAllBytes(temporary,bytes);if(File.Exists(file))File.Delete(file);File.Move(temporary,file);}finally{if(File.Exists(temporary))File.Delete(temporary);}return file;
            }finally{resizeGate.Release();}
        }
        internal static void TestSendSize(){
            string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"send-size-test.txt"),oldCatalog=Catalog.DataPath,oldOutbox=ImageBundle.OutputRoot;
            try{string work=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-work","size-"+Guid.NewGuid().ToString("N").Substring(0,8));Directory.CreateDirectory(work);ImageBundle.OutputRoot=Path.Combine(work,"outbox");Catalog.DataPath=Path.Combine(work,"catalog.json");
                if(new Settings().ResizeSend100)throw new Exception("Default must be off");Catalog.Save(new Settings{ResizeSend100=true});if(!Catalog.Load().ResizeSend100)throw new Exception("Setting persistence");File.WriteAllText(Catalog.DataPath,"{}");if(Catalog.Load().ResizeSend100)throw new Exception("Legacy default");
                using(var form=new SemanticSettingsForm(false,value=>{})){int changes=0;form.AddThumbnailSettings(false,value=>{},()=>{},()=>{},()=>"test",()=>0,()=>false);form.AddSendSizeSettings(false,value=>changes++);var tabs=form.Controls.OfType<System.Windows.Forms.TabControl>().Single();var option=tabs.TabPages.Cast<System.Windows.Forms.TabPage>().Single(page=>page.Text=="전송").Controls[0].Controls.OfType<System.Windows.Forms.CheckBox>().Single();if(changes!=0||option.Checked)throw new Exception("UI initial");option.Checked=true;option.Checked=false;if(changes!=2)throw new Exception("UI callback");}
                string source=Path.Combine(work,"가로 콘.png");using(var image=new System.Drawing.Bitmap(240,120)){using(var g=System.Drawing.Graphics.FromImage(image))g.Clear(System.Drawing.Color.Red);image.Save(source,System.Drawing.Imaging.ImageFormat.Png);}string hash=Digest(source);if(ResizeForSend(source,false,CancellationToken.None)!=source)throw new Exception("Disabled path");string output=ResizeForSend(source,true,CancellationToken.None);DateTime written=File.GetLastWriteTimeUtc(output);if(ResizeForSend(source,true,CancellationToken.None)!=output||written!=File.GetLastWriteTimeUtc(output))throw new Exception("Cache reuse");
                using(var image=System.Drawing.Image.FromFile(output))using(var payload=new ImageClipboard(image)){var bitmap=(System.Drawing.Bitmap)payload.Data.GetData(System.Windows.Forms.DataFormats.Bitmap);if(bitmap.Width!=100||bitmap.Height!=100)throw new Exception("Clipboard dimensions");}
                string gif=Path.Combine(work,"움짤.gif");File.WriteAllBytes(gif,new byte[]{71,73,70,56,57,97,1,0,1,0,128,0,0,0,0,0,255,255,255,33,249,4,0,10,0,0,0,44,0,0,0,0,1,0,1,0,0,2,2,68,1,0,33,249,4,0,10,0,0,0,44,0,0,0,0,1,0,1,0,0,2,2,76,1,0,59});string gifHash=Digest(gif),smallGif=ResizeForSend(gif,true,CancellationToken.None);if(!GifAttachment.AnimatedGif(smallGif)||GifAttachment.FilePayload(smallGif).GetFileDropList()[0]!=smallGif)throw new Exception("Animated file path");
                var originalPair=ImageBundle.Create(new[]{source,gif},BundleMode.Double,CancellationToken.None);if(!ImageBundle.PrepareAttachments(originalPair,false,CancellationToken.None).SequenceEqual(originalPair))throw new Exception("Disabled batch changed");var pair=ImageBundle.PrepareAttachments(originalPair,true,CancellationToken.None).ToArray();if(PreviewPaste.AttachmentFileNames(pair,2)!=String.Join(" ",pair.Select(path=>"\""+Path.GetFullPath(path)+"\"")))throw new Exception("Double picker paths");if(pair.Length!=2||!GifAttachment.AnimatedGif(pair[1]))throw new Exception("Double animation/order");
                var originalPieces=ImageBundle.Create(new[]{source},BundleMode.SplitNine,CancellationToken.None);var pieces=ImageBundle.PrepareAttachments(originalPieces,true,CancellationToken.None).ToArray();if(PreviewPaste.NineFileNames(pieces)!=String.Join(" ",pieces.Select(path=>"\""+Path.GetFullPath(path)+"\"")))throw new Exception("Split picker paths");if(!pieces.Select(Path.GetFileNameWithoutExtension).SequenceEqual(originalPieces.Select(Path.GetFileNameWithoutExtension)))throw new Exception("Split names/order");if(pieces.Length!=9||pieces.Distinct().Count()!=9)throw new Exception("Split order/identity");foreach(string piece in pieces)using(var image=System.Drawing.Image.FromFile(piece))if(image.Width!=100||image.Height!=100)throw new Exception("Split size");
                using(var ready=LongPrepared.Create(Enumerable.Range(0,4).Select(i=>new Entry{Path=source}).ToList(),CancellationToken.None,null,true))if(ready.Parts.Count!=4||ready.Parts.Any(part=>((System.Drawing.Bitmap)part.Data.GetData(System.Windows.Forms.DataFormats.Bitmap)).Width!=100))throw new Exception("Long pieces");
                if(Digest(source)!=hash||Digest(gif)!=gifHash)throw new Exception("Source modified");File.WriteAllText(report,"PASS: opt-in persistence/legacy default/UI callback, original bytes, 100x100 bitmap payload, cache reuse, animated GIF file payload, double GIF/PNG order, nine unique 100x100 files with names/order/common-folder picker validation and long prepared pieces. No system clipboard, Kakao or input.");
            }catch(Exception ex){File.WriteAllText(report,"FAIL: "+ex);Environment.ExitCode=1;}finally{Catalog.DataPath=oldCatalog;ImageBundle.OutputRoot=oldOutbox;}
        }
        public static byte[] Convert(byte[] bytes,CancellationToken cancel,bool resize100=false){string work=Path.Combine(DcShop.CacheRoot,"codec-work",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);string input=Path.Combine(work,"input.asset"),outputBase=Path.Combine(work,"output");File.WriteAllBytes(input,bytes);
            try{string script=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"codecs","convert.py");var info=new ProcessStartInfo(Python(),"\""+script+"\" \""+input+"\" \""+outputBase+"\""+(resize100?" --100":"")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};info.EnvironmentVariables["PYTHONUTF8"]="1";
                using(var process=Process.Start(info))using(cancel.Register(()=>Stop(process))){var output=process.StandardOutput.ReadToEndAsync();var errors=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(75000)){Stop(process);process.WaitForExit(3000);throw new Exception("아카콘 변환 시간이 초과됐어요.");}cancel.ThrowIfCancellationRequested();string json=output.GetAwaiter().GetResult();string stderr=errors.GetAwaiter().GetResult();if(String.IsNullOrWhiteSpace(json))throw new InvalidOperationException("이미지 변환 프로그램 결과가 없어요 (종료 코드 "+process.ExitCode+"). "+(String.IsNullOrWhiteSpace(stderr)?"runtime과 codecs 폴더를 함께 교체해주세요.":stderr.Substring(0,Math.Min(1200,stderr.Length)).Trim()));CodecResult result;try{using(var stream=new MemoryStream(Encoding.UTF8.GetBytes(json)))result=(CodecResult)new DataContractJsonSerializer(typeof(CodecResult)).ReadObject(stream);}catch(SerializationException){throw new InvalidOperationException("이미지 변환 결과 형식이 올바르지 않아요 (종료 코드 "+process.ExitCode+"). "+stderr.Substring(0,Math.Min(1200,stderr.Length)).Trim());}if(result==null||!String.IsNullOrEmpty(result.Error))throw new Exception(result==null?"아카콘 변환에 실패했어요.":result.Error);if(result.Path!=outputBase+".png"&&result.Path!=outputBase+".gif")throw new Exception("변환 결과 경로가 잘못됐어요.");var file=new FileInfo(result.Path);if(!file.Exists||file.Length>30*1024*1024)throw new Exception("변환 결과가 없거나 용량이 너무 커요.");return File.ReadAllBytes(file.FullName);}
            }finally{foreach(string file in Directory.EnumerateFiles(work))File.Delete(file);Directory.Delete(work);}
        }
    }
